<!doctype html><html lang="es"><head><meta charset="utf-8"><style>
@page{margin:0}body{margin:0;background:#f3f3f1;font-family:DejaVu Sans,Arial,sans-serif;color:#242424}.ticket{width:94%;margin:14px auto;background:#fff;border-radius:18px;overflow:hidden}.head{height:120px;background:#252525;text-align:center;padding:8px}.logo{height:104px;max-width:470px;object-fit:contain}.title{text-align:center;font-size:24px;font-weight:bold;margin:18px 0 10px}.status{display:inline-block;background:#dff4e3;color:#18743a;border-radius:18px;padding:8px 28px;font-weight:bold}.code,.money{margin:16px 18px;background:#f1f1ef;border-radius:10px;text-align:center;padding:13px}.code small,.label{display:block;color:#777;font-size:9px;letter-spacing:1px;text-transform:uppercase}.code strong{font-size:21px;letter-spacing:1px}.info{margin:0 20px}.grid{display:table;width:100%;table-layout:fixed}.row{display:table-cell;width:50%;padding:9px 8px;border-bottom:1px solid #ddd;vertical-align:top}.row:first-child{padding-left:0}.row:last-child{padding-right:0}.value{font-size:13px;font-weight:bold;margin-top:4px}.money{display:table;width:calc(100% - 36px);table-layout:fixed}.money div{display:table-cell;text-align:center;border-right:1px solid #ccc}.money div:last-child{border:0}.money small{display:block;color:#777;font-size:9px;letter-spacing:1px}.money strong{font-size:16px}.balance{color:#d45c12}.qr{text-align:center;margin:10px 0}.qr img{width:110px;height:110px}.qr small{display:block;margin-top:4px;letter-spacing:1px;color:#777;font-size:10px}.foot{position:relative;border-top:2px dashed #aaa;margin-top:18px;padding:17px;text-align:center;font-size:11px;letter-spacing:1px}.foot:before,.foot:after{content:"";position:absolute;top:-13px;width:25px;height:25px;background:#f3f3f1;border-radius:50%}.foot:before{left:-13px}.foot:after{right:-13px}.note{font-size:9px;color:#777;letter-spacing:0;margin-top:7px}
</style></head><body><div class="ticket"><div class="head"><img class="logo" src="{{ $logo }}"></div><div class="title">PASE DE RESERVA</div><div style="text-align:center"><span class="status">{{ $booking->booking_status === 'CONFIRMADA' ? 'CONFIRMADA' : $booking->booking_status }}</span></div><div class="code"><small>CÓDIGO DE RESERVA</small><strong>{{ $booking->code }}</strong></div><div class="info"><div class="grid"><div class="row"><div class="label">Cliente</div><div class="value">{{ $booking->customer->name }}</div></div><div class="row"><div class="label">Playroom</div><div class="value">{{ $booking->room->name }} · {{ $booking->room->category->name }}</div></div></div><div class="grid"><div class="row"><div class="label">Fecha</div><div class="value">{{ $booking->starts_at->timezone('America/Santiago')->format('d/m/Y') }}</div></div><div class="row"><div class="label">Horario</div><div class="value">{{ $booking->starts_at->timezone('America/Santiago')->format('H:i') }} — {{ $booking->ends_at->timezone('America/Santiago')->format('H:i') }}</div></div></div><div class="grid"><div class="row"><div class="label">Duración</div><div class="value">{{ $booking->duration_minutes / 60 }} horas</div></div><div class="row"><div class="label">Presentación</div><div class="value">Recepción HH Motel</div></div></div></div><div class="money"><div><small>TOTAL</small><strong>${{ number_format($booking->price_final + $booking->addonsTotal(),0,',','.') }}</strong></div><div><small>PAGADO</small><strong>${{ number_format($paid,0,',','.') }}</strong></div><div><small>SALDO</small><strong class="balance">${{ number_format($balance,0,',','.') }}</strong></div></div><div class="qr"><img src="{{ $qrDataUri }}"><small>{{ $booking->code }}</small></div><div class="foot"><strong>PRESENTAR EN RECEPCIÓN</strong><div class="note">Este pase es un comprobante operacional, no un documento tributario.<br>HH Motel Santiago · Playrooms</div></div></div></body></html>
